// Fan out the configured RSS feed URLs into individual items so the next RSS node can iterate.
const sources = JSON.parse($json.sources);
return sources.map(url => ({ json: { url, topic_filter: $json.topic_filter, max_stories: $json.max_stories } }));

// Score and rank stories across all feeds.
// Keyword overlap with topic_filter + recency boost (last 24h).

const all = $input.all();
const cfg = $('Config').first().json;
const keywords = cfg.topic_filter.split(',').map(k => k.trim().toLowerCase()).filter(Boolean);
const dayMs = 24 * 60 * 60 * 1000;
const now = Date.now();

const scored = all.map(item => {
  const j = item.json;
  const text = `${j.title || ''} ${j.contentSnippet || j.content || ''}`.toLowerCase();
  const keyword_hits = keywords.filter(k => text.includes(k)).length;
  const pub = j.isoDate || j.pubDate ? new Date(j.isoDate || j.pubDate).getTime() : now;
  const age_hours = Math.max(0, (now - pub) / (60 * 60 * 1000));
  const recency_score = age_hours < 24 ? 2 : age_hours < 72 ? 1 : 0;
  return {
    json: {
      title: j.title,
      link: j.link,
      summary: (j.contentSnippet || j.content || '').slice(0, 800),
      pub_date: j.isoDate || j.pubDate,
      score: keyword_hits * 3 + recency_score
    }
  };
});

// Dedupe by title and take the top N.
const seen = new Set();
const ranked = scored
  .filter(i => i.json.score > 0)
  .sort((a, b) => b.json.score - a.json.score)
  .filter(i => { if (seen.has(i.json.title)) return false; seen.add(i.json.title); return true; })
  .slice(0, cfg.max_stories);

if (!ranked.length) {
  throw new Error('No qualifying stories matched the topic filter today.');
}

return ranked;

// Collapse all top stories into a single item with a stories array for one LLM call.
// One call beats N calls for coherent multi-story scripts (the hosts can reference earlier stories).
const stories = $input.all().map((i, idx) => ({
  rank: idx + 1,
  title: i.json.title,
  link: i.json.link,
  summary: i.json.summary
}));

return [{ json: { stories, story_count: stories.length, generated_for: new Date().toISOString().slice(0, 10) } }];

