// Parse OpenAI's JSON-mode response. response_format guarantees parseable JSON in choices[0].message.content.
const response = $input.first().json;
const raw = response.choices?.[0]?.message?.content || '';

let parsed;
try { parsed = JSON.parse(raw); }
catch (e) { throw new Error('Failed to parse JSON-mode output: ' + e.message + '. Got: ' + raw.slice(0, 300)); }

const turns = parsed.turns;
if (!Array.isArray(turns) || !turns.length) throw new Error('Turns array missing or empty in response.');

// Validate every turn before we send anything to ElevenLabs.
const valid_speakers = new Set(['alex', 'jordan']);
turns.forEach((t, i) => {
  if (!valid_speakers.has(t.speaker)) throw new Error(`Turn ${i}: invalid speaker '${t.speaker}'`);
  if (!t.text || t.text.length < 5) throw new Error(`Turn ${i}: text too short or missing`);
  if (t.text.length > 800) throw new Error(`Turn ${i}: text too long (${t.text.length} chars)`);
});

// Emit each turn as a separate item so the next node can synthesize them in sequence.
return turns.map((t, idx) => ({
  json: {
    turn_index: idx,
    total_turns: turns.length,
    speaker: t.speaker,
    text: t.text,
    is_first: idx === 0,
    is_last: idx === turns.length - 1
  }
}));

// Per-persona voice settings — this is the heart of the multi-voice tuning showcase.
// Alex (curious, energetic) and Jordan (dry expert) need different ElevenLabs params.

const PERSONAS = {
  alex: {
    voice_id: 's3TPKV1kjDlVtZbl4Ksh',   // TODO: swap to a brighter younger voice for true multi-voice demo
    settings: {
      stability: 0.35,           // more variation → curious energy
      similarity_boost: 0.80,
      style: 0.45,               // higher style → expressive 'wait, what?' moments
      use_speaker_boost: true
    }
  },
  jordan: {
    voice_id: 's3TPKV1kjDlVtZbl4Ksh', // TODO: swap to a lower measured voice for true multi-voice demo
    settings: {
      stability: 0.65,           // steadier → analyst credibility
      similarity_boost: 0.85,
      style: 0.15,               // low style → dry, deadpan delivery
      use_speaker_boost: true
    }
  }
};

const t = $json;
const persona = PERSONAS[t.speaker];
if (!persona) throw new Error(`No persona config for speaker: ${t.speaker}`);

return [{
  json: {
    ...t,
    voice_id: persona.voice_id,
    voice_settings: persona.settings
  }
}];

// Each item now has the synthesized binary audio. Collect ALL items into a single ordered list
// for the merge step. Tag each binary with its turn_index so order is preserved through downstream nodes.

const items = $input.all();
// Sort by turn_index (defensive — n8n usually preserves order with batching, but binary fan-in can scramble).
items.sort((a, b) => a.json.turn_index - b.json.turn_index);

return items.map((it, idx) => ({
  json: { turn_index: it.json.turn_index, speaker: it.json.speaker, text: it.json.text },
  binary: { [`audio_${String(idx).padStart(3, '0')}`]: it.binary.data }
}));

// Concatenate MP3 binary segments using Buffer.concat — works on n8n Cloud (no Execute Command, no native imports).
// Safe because every ElevenLabs response shares codec (MP3) + sample rate (44.1kHz) + channels (mono).
// MP3 is a stream of self-contained frames so naive byte concatenation produces a valid file every player handles.
// This is byte-identical to ffmpeg's `-c copy` stream-copy concat — same output, no native binary needed.

const items = $input.all();
// Defensive: sort by turn_index in case binary fan-in scrambled order.
items.sort((a, b) => (a.json.turn_index ?? 0) - (b.json.turn_index ?? 0));

const buffers = [];
for (let i = 0; i < items.length; i++) {
  const binKey = Object.keys(items[i].binary || {})[0];
  if (!binKey) throw new Error(`Item ${i} has no binary segment`);
  const buf = await this.helpers.getBinaryDataBuffer(i, binKey);
  buffers.push(buf);
}

const combined = Buffer.concat(buffers);
const episode_date = new Date().toISOString().slice(0, 10);
const transcript = items.map(it => `${it.json.speaker.toUpperCase()}: ${it.json.text}`).join('\n\n');
const total_chars = items.reduce((s, it) => s + it.json.text.length, 0);

return [{
  json: {
    episode_date,
    turn_count: items.length,
    total_chars,
    transcript,
    estimated_seconds: Math.round(total_chars / 15),
    bytes: combined.length
  },
  binary: {
    episode: await this.helpers.prepareBinaryData(combined, `signal-boost-${episode_date}.mp3`, 'audio/mpeg')
  }
}];

// Build a podcast-style RSS item entry and a Slack-friendly summary.
const meta = $('Stitch Audio (Buffer.concat)').first().json;
const s3 = $input.first().json;
const audio_url = s3.Location || `https://${$env.S3_BUCKET}.s3.amazonaws.com/${s3.Key}`;

const rss_item = `<item>
  <title>Signal Boost — ${meta.episode_date}</title>
  <description><![CDATA[${meta.transcript.slice(0, 500)}...]]></description>
  <pubDate>${new Date().toUTCString()}</pubDate>
  <enclosure url="${audio_url}" length="0" type="audio/mpeg"/>
  <itunes:duration>${meta.estimated_seconds}</itunes:duration>
  <guid isPermaLink="false">signal-boost-${meta.episode_date}</guid>
</item>`;

return [{
  json: {
    episode_date: meta.episode_date,
    audio_url,
    transcript: meta.transcript,
    duration_seconds: meta.estimated_seconds,
    turn_count: meta.turn_count,
    total_chars: meta.total_chars,
    rss_item
  }
}];
